import numpy as np

def feature(moves, owner, homes, points, adjacency, turn):
    """Points of the claimed cell / 5 when <= 6 claims remain, else 0."""
    N = adjacency.shape[0]
    remaining = (N - 2) - turn
    if remaining <= 6:
        return points[moves].astype(float) / 5.0
    return np.zeros(len(moves), dtype=float)

import numpy as np

def feature(moves, owner, points, adjacency, homes, turn):
    """Sum over empty 5-point cells j of 1/(1+d[j]) where d is BFS distance (capped at 3) from the candidate through empty cells, divided by 3."""
    N = owner.shape[0]
    E = (owner == 0)
    pts = points.astype(float)
    five = E & (pts == 5)
    adj = adjacency
    out = np.zeros(len(moves), dtype=float)
    for idx, c in enumerate(moves):
        d = np.full(N, 4, dtype=int)
        d[c] = 0
        frontier = [c]
        for depth in range(1, 4):
            nxt = []
            for u in frontier:
                for v in np.nonzero(adj[u])[0]:
                    if E[v] and d[v] == 4:
                        d[v] = depth
                        nxt.append(v)
            frontier = nxt
            if not frontier:
                break
        total = 0.0
        for j in np.nonzero(five)[0]:
            if d[j] <= 3:
                total += 1.0 / (1.0 + d[j])
        out[idx] = total / 3.0
    return out
